import base64, pty, os, sys, time, select, fcntl, struct, termios, struct

def extract_png(raw):
    # Search for \x89PNG inside base64 chunks
    parts = raw.split(b"\x1b")
    for p in parts:
        if p.startswith(b"_G") or p.startswith(b"]1337"):
            semi = p.find(b";")
            if semi != -1:
                b64 = p[semi+1:].replace(b"\r", b"").replace(b"\n", b"").replace(b"\\", b"").replace(b"\x07", b"")
                # Fix b64 padding
                b64 = b64.split(b"\x1b")[0].split(b"\x07")[0]
                mod = len(b64) % 4
                if mod != 0:
                    b64 += b"=" * (4 - mod)
                try:
                    data = base64.b64decode(b64)
                    if data.startswith(b"\x89PNG"):
                        return data
                except Exception:
                    pass
    return None

def test_winsize(rows, cols, xpixels, ypixels, args=["Threads"]):
    r_pipe, w_pipe = os.pipe()

    pid, fd = pty.fork()
    if pid == 0:
        os.close(w_pipe)
        os.dup2(r_pipe, 0)
        os.close(r_pipe)

        winsz = struct.pack("HHHH", rows, cols, xpixels, ypixels)
        fcntl.ioctl(1, termios.TIOCSWINSZ, winsz)
        os.execv("./executable", ["./executable"] + args)
    else:
        os.close(r_pipe)

        out = b""
        start = time.time()
        sent_json = False

        while time.time() - start < 1.5:
            r, _, _ = select.select([fd], [], [], 0.05)
            if r:
                try:
                    data = os.read(fd, 4096)
                    if not data: break
                    out += data
                    if b"\x1b_G" in data:
                        os.write(fd, b"\x1b_Gi=1;OK\x1b\\")
                    if b"\x1b[c" in data:
                        os.write(fd, b"\x1b[?62;4c")
                    if b"\x1b[14t" in data:
                        os.write(fd, f"\x1b[4;{ypixels};{xpixels}t".encode())
                        if not sent_json:
                            os.write(w_pipe, b"{\"Threads\": 42}\n")
                            sent_json = True
                except OSError:
                    break

        os.close(w_pipe)
        try:
            os.kill(pid, 9)
            os.waitpid(pid, 0)
        except: pass
        os.close(fd)

        png_bytes = extract_png(out)
        if png_bytes:
            width, height = struct.unpack(">II", png_bytes[16:24])
            print(f"Term: {cols}x{rows} ({xpixels}x{ypixels}px) Args: {args} -> Image: {width}x{height}px")
        else:
            print("No image found for", args)

