func drawBox(img *image.RGBA, x, y, w, h int, col color.Color) {
	cr, cg, cb, ca := col.RGBA()
	r, g, b, a := uint8(cr>>8), uint8(cg>>8), uint8(cb>>8), uint8(ca>>8)
	for py := y; py < y+h; py++ {
		for px := x; px < x+w; px++ {
			if px >= 0 && px < img.Bounds().Dx() && py >= 0 && py < img.Bounds().Dy() {
				img.SetRGBA(px, py, color.RGBA{r, g, b, a})
			}
		}
	}
}

func drawLine(img *image.RGBA, x0, y0, x1, y1 int, col color.RGBA) {
	dx := abs(x1 - x0)
	dy := abs(y1 - y0)
	sx, sy := -1, -1
	if x0 < x1 {
		sx = 1
	}
	if y0 < y1 {
		sy = 1
	}
	err := dx - dy

	for {
		if x0 >= 0 && x0 < img.Bounds().Dx() && y0 >= 0 && y0 < img.Bounds().Dy() {
			img.SetRGBA(x0, y0, col)
		}
		if x0 == x1 && y0 == y1 {
			break
		}
		e2 := 2 * err
		if e2 > -dy {
			err -= dy
			x0 += sx
		}
		if e2 < dx {
			err += dx
			y0 += sy
		}
	}
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func encodeKitty(pngData []byte) string {
	b64 := base64.StdEncoding.EncodeToString(pngData)
	var sb strings.Builder

	chunkSize := 4096
	n := len(b64)
	for i := 0; i < n; i += chunkSize {
		end := i + chunkSize
		m := 1
		if end >= n {
			end = n
			m = 0
		}
		chunk := b64[i:end]
		if i == 0 {
			sb.WriteString(fmt.Sprintf("\x1b_Ga=T,f=100,t=d,i=2,X=0,Y=0,q=2,m=%d;%s\x1b\\", m, chunk))
		} else {
			sb.WriteString(fmt.Sprintf("\x1b_Gm=%d;%s\x1b\\", m, chunk))
		}
	}
	return sb.String()
}

func encodeITerm2(pngData []byte, w, h int) string {
	b64 := base64.StdEncoding.EncodeToString(pngData)
	return fmt.Sprintf("\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\x07", w, h, b64)
}

func isatty(fd uintptr) bool {
	var sz struct {
		rows, cols, xpixels, ypixels uint16
	}
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCSWINSZ), uintptr(unsafe.Pointer(&sz)))
	return err == 0
}

func main() {
	termProg := os.Getenv("TERM_PROGRAM")
	if termProg != "iTerm.app" && termProg != "iTerm2" && termProg != "warp" && termProg != "WarpTerminal" {
		fmt.Print("\x1b[c")
	}

	flag.CommandLine.Init("jplot", flag.ContinueOnError)
	flag.CommandLine.SetOutput(os.Stderr)
	flag.Usage = printUsage

	interval := flag.Duration("interval", 1*time.Second, "When url is provided, defines the interval between fetches. Note that counter fields are computed based on this interval.")
	rowsFlag := flag.Int("rows", 0, "Limits the height of the graph output.")
	stepsFlag := flag.Int("steps", 100, "Number of values to plot.")
	urlFlag := flag.String("url", "", "URL to fetch every second. Read JSON objects from stdin if not specified.")

	if err := flag.CommandLine.Parse(os.Args[1:]); err != nil {
		if err == flag.ErrHelp {
			os.Exit(0)
		}
		os.Exit(2)
	}

	isStdoutTTY := isatty(os.Stdout.Fd())
	proto, termRows, termCols, termXpx, termYpx := detectTerminal(isStdoutTTY)
	if proto == protoUnknown {
		fmt.Printf("jplot:  iTerm2, Kitty, or DRCS Sixel graphics required\n")
		os.Exit(1)
	}

	specs, err := parseSpecs(flag.CommandLine.Args())
	if err != nil {
		if err.Error() == "no specs provided" {
			printUsage()
			os.Exit(1)
		}
		fmt.Printf("jplot:  %s\n", err.Error())
		os.Exit(1)
	}

	isStdinTTY := isatty(os.Stdin.Fd())

	if *urlFlag == "" && isStdinTTY {
		fmt.Printf("jplot:  neither --url nor stdin is provided\n")
		os.Exit(1)
	}

	imgW, imgH := queryPixelDimensions(proto, termRows, termCols, termXpx, termYpx, isStdoutTTY)
	cellW := imgW / termCols
	cellH := imgH / termRows
	if cellW <= 0 {
		cellW = 10
	}
	if cellH <= 0 {
		cellH = 25
	}

	graphRows := termRows
	if *rowsFlag > 0 {
		graphRows = *rowsFlag
	}

	renderW := (termCols - 1) * cellW
	renderH := graphRows*cellH - 2
	if renderW <= 0 {
		renderW = 800
	}
	if renderH <= 0 {
		renderH = 600
	}

	graphs := make([]*GraphState, len(specs))
	for i, gSpec := range specs {
		gState := &GraphState{}
		for _, sSpec := range gSpec.series {
			sState := &SeriesState{
				spec:    sSpec,
				history: make([]float64, 0, *stepsFlag),
			}
			gState.series = append(gState.series, sState)
		}
		graphs[i] = gState
	}

	c := make(chan os.Signal, 1)
	signal.Notify(c, os.Interrupt, syscall.SIGTERM)
	go func() {
		<-c
		fmt.Print("\x1b[?25h\n")
		os.Exit(0)
	}()

	firstFrame := true

	processJSON := func(jsonBytes []byte) bool {
		var jsonObj map[string]interface{}
		if err := json.Unmarshal(jsonBytes, &jsonObj); err != nil {
			fmt.Printf("jplot:  Data source error:  input error: %s\n", err.Error())
			return false
		}

		for _, g := range graphs {
			for _, s := range g.series {
				val, err := getJSONValue(jsonObj, s.spec.path)
				if err != nil {
					fmt.Printf("jplot:  Data source error:  %s\n", err.Error())
					return false
				}

				plotVal := val
				if s.spec.counter {
					if !s.hasPrev {
						s.hasPrev = true
						s.lastCounter = val
						plotVal = 0
					} else {
						diff := val - s.lastCounter
						if diff < 0 {
							diff = 0
						}
						s.lastCounter = val
						plotVal = diff
					}
				}

				s.history = append(s.history, plotVal)
				if len(s.history) > *stepsFlag {
					s.history = s.history[1:]
				}
			}
		}

		pngBytes := renderPNG(graphs, renderW, renderH, *stepsFlag)

		if firstFrame {
			fmt.Print("\x1b[?25l")
			for i := 0; i < graphRows; i++ {
				fmt.Print("\r\n")
			}
			fmt.Printf("\x1b[%dA\x1b[s", graphRows)
			firstFrame = false
		} else {
			fmt.Print("\x1b[u")
		}

		switch proto {
		case protoITerm2:
			fmt.Print(encodeITerm2(pngBytes, renderW, renderH))
		case protoKitty, protoSixel:
			fmt.Print(encodeKitty(pngBytes))
		}
		fmt.Print("\x1b[u\x1b[s")
		return true
	}

	if *urlFlag != "" {
		ticker := time.NewTicker(*interval)
		defer ticker.Stop()

		for {
			resp, err := http.Get(*urlFlag)
			if err != nil {
				fmt.Printf("jplot:  Data source error:  %s\n", err.Error())
			} else {
				body, err := io.ReadAll(resp.Body)
				resp.Body.Close()
				if err == nil {
					processJSON(body)
				}
			}
			<-ticker.C
		}
	} else {
		scanner := bufio.NewScanner(os.Stdin)
		for scanner.Scan() {
			line := scanner.Bytes()
			if len(bytes.TrimSpace(line)) == 0 {
				continue
			}
			if !processJSON(line) {
				os.Exit(1)
			}
		}
		if err := scanner.Err(); err != nil {
			fmt.Printf("jplot:  Data source error:  input error: %s\n", err.Error())
			os.Exit(1)
		}
	}
}
EOF
go build -o test_executable main.go font.go
"}

actions.command:
cat << 'EOF' > main.go
package main

import (
	"bufio"
	"bytes"
	"encoding/base64"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"image"
	"image/color"
	"image/png"
	"io"
	"math"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"strings"
	"syscall"
	"time"
	"unsafe"
)

type SeriesSpec struct {
	path    string
	counter bool
	marker  bool
}

type GraphSpec struct {
	series []SeriesSpec
}

type termProtocol int

const (
	protoUnknown termProtocol = iota
	protoITerm2
	protoKitty
	protoSixel
)

var defaultPalette = []color.RGBA{
	{0x00, 0x74, 0xD9, 0xFF}, // Blue
	{0x00, 0xD9, 0x65, 0xFF}, // Green
	{0xD9, 0x00, 0x74, 0xFF}, // Pink
	{0x00, 0xD9, 0xD2, 0xFF}, // Cyan
	{0xD9, 0x65, 0x00, 0xFF}, // Orange
	{0x6A, 0xC3, 0xCB, 0xFF}, // Light Teal
	{0x2A, 0xBE, 0x89, 0xFF}, // Mint
	{0x6E, 0x80, 0x8B, 0xFF}, // Gray
	{0xF0, 0xAE, 0x5A, 0xFF}, // Gold
}

type SeriesState struct {
	spec        SeriesSpec
	history     []float64
	hasPrev     bool
	prevVal     float64
	lastCounter float64
	color       color.RGBA
}

type GraphState struct {
	series []*SeriesState
}

func printUsage() {
	out := flag.CommandLine.Output()
	fmt.Fprintf(out, "Usage: jplot [OPTIONS] FIELD_SPEC [FIELD_SPEC...]:\n\nOPTIONS:\n")
	flag.PrintDefaults()
	fmt.Fprintf(out, "\nFIELD_SPEC: [<option>[,<option>...]:]path\n")
	fmt.Fprintf(out, "  option:\n")
	fmt.Fprintf(out, "    - counter: Computes the difference with the last value. The value must increase monotonically.\n")
	fmt.Fprintf(out, "    - marker: When the value is none-zero, a vertical line is drawn.\n")
	fmt.Fprintf(out, "  path:\n")
	fmt.Fprintf(out, "    JSON field path (eg: field.sub-field).\n")
}

func parseSpecs(args []string) ([]GraphSpec, error) {
	if len(args) == 0 {
		return nil, errors.New("no specs provided")
	}

	graphs := make([]GraphSpec, 0, len(args))
	for _, arg := range args {
		if arg == "" {
			return nil, fmt.Errorf("Data source error:  cannot get :  does not exist.")
		}
		rawSeries := strings.Split(arg, "+")
		var g GraphSpec
		for _, s := range rawSeries {
			var spec SeriesSpec
			if strings.Contains(s, ":") {
				parts := strings.SplitN(s, ":", 2)
				opts := strings.Split(parts[0], ",")
				for _, opt := range opts {
					opt = strings.TrimSpace(opt)
					switch opt {
					case "counter":
						spec.counter = true
					case "marker":
						spec.marker = true
					default:
						return nil, fmt.Errorf("Cannot parse spec:  invalid field option: %s", opt)
					}
				}
				spec.path = parts[1]
			} else {
				spec.path = s
			}
			g.series = append(g.series, spec)
		}
		graphs = append(graphs, g)
	}
	return graphs, nil
}

func getWinsize(fd uintptr) (rows, cols, xpixels, ypixels int, err error) {
	var sz struct {
		rows, cols, xpixels, ypixels uint16
	}
	_, _, sysErr := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCSWINSZ), uintptr(unsafe.Pointer(&sz)))
	if sysErr != 0 {
		return 0, 0, 0, 0, sysErr
	}
	return int(sz.rows), int(sz.cols), int(sz.xpixels), int(sz.ypixels), nil
}

func detectTerminal(isTTY bool) (termProtocol, int, int, int, int) {
	rows, cols, xpixels, ypixels, _ := getWinsize(os.Stdout.Fd())
	if rows == 0 {
		rows = 24
	}
	if cols == 0 {
		cols = 80
	}

	termProg := os.Getenv("TERM_PROGRAM")
	if termProg == "iTerm.app" || termProg == "iTerm2" || termProg == "warp" || termProg == "WarpTerminal" {
		return protoITerm2, rows, cols, xpixels, ypixels
	}

	if !isTTY {
		return protoUnknown, rows, cols, xpixels, ypixels
	}

	// Probe terminal via escape sequences
	// Write Kitty query & DA query
	os.Stdout.WriteString("\x1b_Gi=1,a=q,t=d,f=24\x1b\\\x1b[c")

	respBuf := make([]byte, 1024)
	nChan := make(chan int, 1)
	go func() {
		n, _ := os.Stdin.Read(respBuf)
		nChan <- n
	}()

	select {
	case n := <-nChan:
		resp := string(respBuf[:n])
		if strings.Contains(resp, "\x1b_G") && (strings.Contains(resp, "OK") || strings.Contains(resp, "i=1")) {
			return protoKitty, rows, cols, xpixels, ypixels
		}
		if strings.Contains(resp, "\x1b[?6") && strings.Contains(resp, ";4;") {
			return protoSixel, rows, cols, xpixels, ypixels
		}
	case <-time.After(150 * time.Millisecond):
	}

	if termProg == "iTerm.app" || termProg == "iTerm2" {
		return protoITerm2, rows, cols, xpixels, ypixels
	}

	return protoKitty, rows, cols, xpixels, ypixels
}

func queryPixelDimensions(proto termProtocol, rows, cols, xpixels, ypixels int, isTTY bool) (int, int) {
	if xpixels > 0 && ypixels > 0 {
		return xpixels, ypixels
	}

	if isTTY {
		if proto == protoITerm2 {
			os.Stdout.WriteString("\x1b]1337;ReportCellSize\x07")
		} else {
			os.Stdout.WriteString("\x1b[14t")
		}

		respBuf := make([]byte, 1024)
		nChan := make(chan int, 1)
		go func() {
			n, _ := os.Stdin.Read(respBuf)
			nChan <- n
		}()

		select {
		case n := <-nChan:
			resp := string(respBuf[:n])
			if proto == protoITerm2 && strings.Contains(resp, "ReportCellSize=") {
				parts := strings.Split(resp, "ReportCellSize=")
				if len(parts) > 1 {
					clean := strings.Split(parts[1], "\x07")[0]
					dims := strings.Split(clean, ";")
					if len(dims) == 2 {
						h, _ := strconv.ParseFloat(dims[0], 64)
						w, _ := strconv.ParseFloat(dims[1], 64)
						if w > 0 && h > 0 {
							return int(w * float64(cols)), int(h * float64(rows))
						}
					}
				}
			} else if strings.Contains(resp, "\x1b[4;") {
				parts := strings.Split(resp, "\x1b[4;")
				if len(parts) > 1 {
					clean := strings.Split(parts[1], "t")[0]
					dims := strings.Split(clean, ";")
					if len(dims) == 2 {
						h, _ := strconv.Atoi(dims[0])
						w, _ := strconv.Atoi(dims[1])
						if w > 0 && h > 0 {
							return w, h
						}
					}
				}
			}
		case <-time.After(150 * time.Millisecond):
		}
	}

	return cols * 10, rows * 25
}

func getJSONValue(obj map[string]interface{}, path string) (float64, error) {
	parts := strings.Split(path, ".")
	var current interface{} = obj

	for i, key := range parts {
		m, ok := current.(map[string]interface{})
		if !ok {
			return 0, fmt.Errorf("cannot get %s: %s is not an object. map[]", path, key)
		}
		val, exists := m[key]
		if !exists {
			return 0, fmt.Errorf("cannot get %s: %s does not exist.", path, key)
		}
		if i == len(parts)-1 {
			switch v := val.(type) {
			case float64:
				return v, nil
			case int:
				return float64(v), nil
			case int64:
				return float64(v), nil
			case json.Number:
				f, err := v.Float64()
				if err != nil {
					return 0, fmt.Errorf("invalid type %s: %v", path, v)
				}
				return f, nil
			default:
				return 0, fmt.Errorf("invalid type %s: %T", path, val)
			}
		}
		current = val
	}
	return 0, fmt.Errorf("cannot get %s: %s does not exist.", path, path)
}

func renderPNG(graphs []*GraphState, imgW, imgH, maxSteps int) []byte {
	img := image.NewRGBA(image.Rect(0, 0, imgW, imgH))

	numGraphs := len(graphs)
	if numGraphs == 0 {
		var buf bytes.Buffer
		png.Encode(&buf, img)
		return buf.Bytes()
	}

	subH := imgH / numGraphs
	colorIndex := 0

	for gIdx, g := range graphs {
		yStart := gIdx * subH
		yEnd := (gIdx + 1) * subH

		paddingLeft := 10
		paddingRight := 10
		paddingTop := 22
		paddingBottom := 10

		plotXMin := paddingLeft
		plotXMax := imgW - paddingRight - 60
		if plotXMax <= plotXMin {
			plotXMax = plotXMin + 1
		}

		plotYMin := yStart + paddingTop
		plotYMax := yEnd - paddingBottom
		if plotYMax <= plotYMin {
			plotYMax = plotYMin + 1
		}

		minVal := math.MaxFloat64
		maxVal := -math.MaxFloat64
		hasData := false

		for _, s := range g.series {
			if s.color.A == 0 {
				s.color = defaultPalette[colorIndex%len(defaultPalette)]
				colorIndex++
			}
			if !s.spec.marker {
				for _, v := range s.history {
					if v < minVal {
						minVal = v
					}
					if v > maxVal {
						maxVal = v
					}
					hasData = true
				}
			}
		}

		if !hasData || minVal == math.MaxFloat64 {
			minVal = 0
			maxVal = 1
		} else if minVal == maxVal {
			if minVal == 0 {
				maxVal = 1
			} else {
				maxVal = minVal * 1.1
				minVal = minVal * 0.9
			}
		}

		gridColor := color.RGBA{179, 179, 179, 56}
		for i := 0; i <= 3; i++ {
			gy := plotYMax - i*(plotYMax-plotYMin)/3
			for gx := plotXMin; gx <= plotXMax; gx += 4 {
				if gx < imgW {
					img.SetRGBA(gx, gy, gridColor)
				}
			}
		}

		maxLabel := fmt.Sprintf("%.2g", maxVal)
		minLabel := fmt.Sprintf("%.2g", minVal)
		drawString(img, maxLabel, plotXMax+5, plotYMin, color.RGBA{180, 180, 180, 255})
		drawString(img, minLabel, plotXMax+5, plotYMax-10, color.RGBA{180, 180, 180, 255})

		for _, s := range g.series {
			n := len(s.history)
			if n == 0 {
				continue
			}

			if s.spec.marker {
				for i, v := range s.history {
					if v != 0 {
						var x int
						if maxSteps <= 1 {
							x = plotXMax
						} else {
							x = plotXMin + i*(plotXMax-plotXMin)/(maxSteps-1)
						}
						for my := plotYMin; my <= plotYMax; my++ {
							if x >= 0 && x < imgW && my >= 0 && my < imgH {
								img.SetRGBA(x, my, s.color)
							}
						}
					}
				}
			} else {
				var prevX, prevY int
				fillColor := color.RGBA{s.color.R, s.color.G, s.color.B, 40}

				for i, v := range s.history {
					var x int
					if maxSteps <= 1 {
						x = plotXMax
					} else {
						x = plotXMin + i*(plotXMax-plotXMin)/(maxSteps-1)
					}
					norm := (v - minVal) / (maxVal - minVal)
					if norm < 0 {
						norm = 0
					}
					if norm > 1 {
						norm = 1
					}
					y := plotYMax - int(norm*float64(plotYMax-plotYMin))

					for fillY := y; fillY <= plotYMax; fillY++ {
						if x >= 0 && x < imgW && fillY >= 0 && fillY < imgH {
							img.SetRGBA(x, fillY, fillColor)
						}
					}

					if i > 0 {
						drawLine(img, prevX, prevY, x, y, s.color)
					}
					prevX = x
					prevY = y
				}
			}
		}

		legendX := plotXMin
		legendY := yStart + 4

		totalLen := 0
		for _, s := range g.series {
			lastVal := 0.0
			if len(s.history) > 0 {
				lastVal = s.history[len(s.history)-1]
			}
			lbl := fmt.Sprintf("%s: %.2g", s.spec.path, lastVal)
			totalLen += len(lbl)*7 + 20
		}
		boxW := totalLen + 10
		boxH := 16

		drawBox(img, legendX, legendY, boxW, boxH, color.RGBA{0, 0, 0, 100})

		currX := legendX + 5
		for _, s := range g.series {
			drawBox(img, currX, legendY+4, 8, 8, s.color)
			currX += 12

			lastVal := 0.0
			if len(s.history) > 0 {
				lastVal = s.history[len(s.history)-1]
			}
			lbl := fmt.Sprintf("%s: %.2g ", s.spec.path, lastVal)
			drawString(img, lbl, currX, legendY+2, color.RGBA{255, 255, 255, 255})
			currX += len(lbl) * 7
		}
	}

	var buf bytes.Buffer
	png.Encode(&buf, img)
	return buf.Bytes()
}

func drawBox(img *image.RGBA, x, y, w, h int, col color.Color) {
	cr, cg, cb, ca := col.RGBA()
	r, g, b, a := uint8(cr>>8), uint8(cg>>8), uint8(cb>>8), uint8(ca>>8)
	for py := y; py < y+h; py++ {
		for px := x; px < x+w; px++ {
			if px >= 0 && px < img.Bounds().Dx() && py >= 0 && py < img.Bounds().Dy() {
				img.SetRGBA(px, py, color.RGBA{r, g, b, a})
			}
		}
	}
}

func drawLine(img *image.RGBA, x0, y0, x1, y1 int, col color.RGBA) {
	dx := abs(x1 - x0)
	dy := abs(y1 - y0)
	sx, sy := -1, -1
	if x0 < x1 {
		sx = 1
	}
	if y0 < y1 {
		sy = 1
	}
	err := dx - dy

	for {
		if x0 >= 0 && x0 < img.Bounds().Dx() && y0 >= 0 && y0 < img.Bounds().Dy() {
			img.SetRGBA(x0, y0, col)
		}
		if x0 == x1 && y0 == y1 {
			break
		}
		e2 := 2 * err
		if e2 > -dy {
			err -= dy
			x0 += sx
		}
		if e2 < dx {
			err += dx
			y0 += sy
		}
	}
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func encodeKitty(pngData []byte) string {
	b64 := base64.StdEncoding.EncodeToString(pngData)
	var sb strings.Builder

	chunkSize := 4096
	n := len(b64)
	for i := 0; i < n; i += chunkSize {
		end := i + chunkSize
		m := 1
		if end >= n {
			end = n
			m = 0
		}
		chunk := b64[i:end]
		if i == 0 {
			sb.WriteString(fmt.Sprintf("\x1b_Ga=T,f=100,t=d,i=2,X=0,Y=0,q=2,m=%d;%s\x1b\\", m, chunk))
		} else {
			sb.WriteString(fmt.Sprintf("\x1b_Gm=%d;%s\x1b\\", m, chunk))
		}
	}
	return sb.String()
}

func encodeITerm2(pngData []byte, w, h int) string {
	b64 := base64.StdEncoding.EncodeToString(pngData)
	return fmt.Sprintf("\x1b]1337;File=preserveAspectRatio=1;width=%dpx;height=%dpx;inline=1:%s\x07", w, h, b64)
}

func isatty(fd uintptr) bool {
	var sz struct {
		rows, cols, xpixels, ypixels uint16
	}
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCSWINSZ), uintptr(unsafe.Pointer(&sz)))
	return err == 0
}

func main() {
	termProg := os.Getenv("TERM_PROGRAM")
	if termProg != "iTerm.app" && termProg != "iTerm2" && termProg != "warp" && termProg != "WarpTerminal" {
		fmt.Print("\x1b[c")
	}

	flag.CommandLine.Init("jplot", flag.ContinueOnError)
	flag.CommandLine.SetOutput(os.Stderr)
	flag.Usage = printUsage

	interval := flag.Duration("interval", 1*time.Second, "When url is provided, defines the interval between fetches. Note that counter fields are computed based on this interval.")
	rowsFlag := flag.Int("rows", 0, "Limits the height of the graph output.")
	stepsFlag := flag.Int("steps", 100, "Number of values to plot.")
	urlFlag := flag.String("url", "", "URL to fetch every second. Read JSON objects from stdin if not specified.")

	if err := flag.CommandLine.Parse(os.Args[1:]); err != nil {
		if err == flag.ErrHelp {
			os.Exit(0)
		}
		os.Exit(2)
