	for gIdx, g := range graphs {
		yStart := gIdx * subH
		yEnd := (gIdx + 1) * subH

		paddingLeft := 10
		paddingRight := 10
		paddingTop := 22
		paddingBottom := 10

		plotXMin := paddingLeft
		plotXMax := imgW - paddingRight - 60
		if plotXMax <= plotXMin {
			plotXMax = plotXMin + 1
		}

		plotYMin := yStart + paddingTop
		plotYMax := yEnd - paddingBottom
		if plotYMax <= plotYMin {
			plotYMax = plotYMin + 1
		}

