func getWinsize(fd uintptr) (rows, cols, xpixels, ypixels int, err error) {
	var sz struct {
		rows, cols, xpixels, ypixels uint16
	}
	_, _, sysErr := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCSWINSZ), uintptr(unsafe.Pointer(&sz)))
	if sysErr != 0 {
		return 0, 0, 0, 0, sysErr
	}
	return int(sz.rows), int(sz.cols), int(sz.xpixels), int(sz.ypixels), nil
}

func detectTerminal(isTTY bool) (termProtocol, int, int, int, int) {
	rows, cols, xpixels, ypixels, _ := getWinsize(os.Stdout.Fd())
	if rows == 0 {
		rows = 24
	}
	if cols == 0 {
		cols = 80
	}

	termProg := os.Getenv("TERM_PROGRAM")
	if termProg == "iTerm.app" || termProg == "iTerm2" || termProg == "warp" || termProg == "WarpTerminal" {
		return protoITerm2, rows, cols, xpixels, ypixels
	}

	if !isTTY {
		return protoUnknown, rows, cols, xpixels, ypixels
	}

	os.Stdout.WriteString("\x1b_Gi=1,a=q,t=d,f=24\x1b\\\x1b[c")

	respBuf := make([]byte, 1024)
	nChan := make(chan int, 1)
	go func() {
		n, _ := os.Stdin.Read(respBuf)
		nChan <- n
	}()

	select {
	case n := <-nChan:
		resp := string(respBuf[:n])
		if strings.Contains(resp, "\x1b_G") && (strings.Contains(resp, "OK") || strings.Contains(resp, "i=1")) {
			return protoKitty, rows, cols, xpixels, ypixels
		}
		if strings.Contains(resp, "\x1b[?6") && strings.Contains(resp, ";4;") {
			return protoSixel, rows, cols, xpixels, ypixels
		}
	case <-time.After(150 * time.Millisecond):
	}

	if termProg == "iTerm.app" || termProg == "iTerm2" {
		return protoITerm2, rows, cols, xpixels, ypixels
	}

	return protoKitty, rows, cols, xpixels, ypixels
}

func queryPixelDimensions(proto termProtocol, rows, cols, xpixels, ypixels int, isTTY bool) (int, int) {
	if xpixels > 0 && ypixels > 0 {
		return xpixels, ypixels
	}

	if isTTY {
		if proto == protoITerm2 {
			os.Stdout.WriteString("\x1b]1337;ReportCellSize\x07")
		} else {
			os.Stdout.WriteString("\x1b[14t")
		}

		respBuf := make([]byte, 1024)
		nChan := make(chan int, 1)
		go func() {
			n, _ := os.Stdin.Read(respBuf)
			nChan <- n
		}()

		select {
		case n := <-nChan:
			resp := string(respBuf[:n])
			if proto == protoITerm2 && strings.Contains(resp, "ReportCellSize=") {
				parts := strings.Split(resp, "ReportCellSize=")
				if len(parts) > 1 {
					clean := strings.Split(parts[1], "\x07")[0]
					dims := strings.Split(clean, ";")
					if len(dims) == 2 {
						h, _ := strconv.ParseFloat(dims[0], 64)
						w, _ := strconv.ParseFloat(dims[1], 64)
						if w > 0 && h > 0 {
							return int(w * float64(cols)), int(h * float64(rows))
						}
					}
				}
			} else if strings.Contains(resp, "\x1b[4;") {
				parts := strings.Split(resp, "\x1b[4;")
				if len(parts) > 1 {
					clean := strings.Split(parts[1], "t")[0]
					dims := strings.Split(clean, ";")
					if len(dims) == 2 {
						h, _ := strconv.Atoi(dims[0])
						w, _ := strconv.Atoi(dims[1])
						if w > 0 && h > 0 {
							return w, h
						}
					}
				}
			}
		case <-time.After(150 * time.Millisecond):
		}
	}

	return cols * 10, rows * 25
}

func getJSONValue(obj map[string]interface{}, path string) (float64, error) {
	parts := strings.Split(path, ".")
	var current interface{} = obj

	for i, key := range parts {
		m, ok := current.(map[string]interface{})
		if !ok {
			return 0, fmt.Errorf("cannot get %s: %s is not an object. map[]", path, key)
		}
		val, exists := m[key]
		if !exists {
			return 0, fmt.Errorf("cannot get %s: %s does not exist.", path, key)
		}
		if i == len(parts)-1 {
			switch v := val.(type) {
			case float64:
				return v, nil
			case int:
				return float64(v), nil
			case int64:
				return float64(v), nil
			case json.Number:
				f, err := v.Float64()
				if err != nil {
					return 0, fmt.Errorf("invalid type %s: %v", path, v)
				}
				return f, nil
			default:
				return 0, fmt.Errorf("invalid type %s: %T", path, val)
			}
		}
		current = val
	}
	return 0, fmt.Errorf("cannot get %s: %s does not exist.", path, path)
}

